step.action:
Call MCP tool `execute_sql` with:
      - url: {{db_url}}
      - api_key: {{service_key}}
      - sql: "SELECT seq, name, description, applied_at FROM public._schema_migrations ORDER BY seq;"

step.output:
📋 **Migration Context**
      - Local migrations: {{local_count}}
      - DB applied: {{db_count}}
      - Pending (need apply): {{pending_count}}
      - Orphaned (DB only): {{orphaned_count}}

step.action:
Create migration file with template:
      -- Migration: {{description}}
      -- Version: {{next_seq}}
      -- Created: {{date}}

      -- ===== UP =====
      -- Add your schema changes here


      -- ===== Register Migration =====
      INSERT INTO public._schema_migrations (seq, name, description, story)
      VALUES ('{{next_seq}}', '{{description_slug}}', '{{description}}', '{{story_key}}')
      ON CONFLICT (seq) DO NOTHING;

Create rollback file with template:
      -- Rollback for Migration: {{description}}
      -- Version: {{next_seq}}
      -- Created: {{date}}

      -- ===== DOWN =====
      -- Add rollback logic here


      -- ===== De-register Migration =====
      DELETE FROM public._schema_migrations WHERE seq = '{{next_seq}}';

Append new entry:
      - seq: {{next_seq}}
        name: {{description_slug}}
        description: {{description}}
        created_at: {{date}}
        status: pending

step.output:
📋 **Pending Migrations** (in DB but not yet applied)
      {{#each pending_migrations}}
      - [{{seq}}] {{description}}
      {{/each}}

check.output:
❌ **Migration [{{failed_seq}}] Failed**
          Error: {{error_message}}

          Migrations applied before failure:
          {{#each applied_before_failure}}
          - [{{seq}}] {{description}} ✓
          {{/each}}

          ⚠️ The failed migration and remaining migrations were NOT applied.
          Fix the SQL error and retry `db-migration apply`.

step.action:
Call MCP tool `execute_sql` with:
      - url: {{db_url}}
      - api_key: {{service_key}}
      - sql: "SELECT seq, name, description, applied_at FROM public._schema_migrations ORDER BY seq DESC LIMIT 1;"

step.output:
⚠️ **Rollback Warning**
      Rolling back will execute DOWN migration which may:
      - Drop tables or columns
      - Remove data
      - Cannot be easily undone

      **Last Applied Migration (from DB):**
      - Version: {{last_seq}}
      - Name: {{last_name}}
      - Description: {{last_description}}
      - Applied: {{last_applied_at}}

check.action:
Call MCP tool `execute_sql` with:
        - url: {{db_url}}
        - api_key: {{service_key}}
        - sql: {{rollback_sql_content}}

step.output:
📊 **Migration Status Report**

      **Source of Truth: `public._schema_migrations` table in database**

      **Summary:**
      | Source | Count |
      |--------|-------|
      | Local manifest | {{local_count}} |
      | Database applied | {{db_count}} |
      | Pending (local only) | {{pending_count}} |
      | Orphaned (DB only) | {{orphaned_count}} |
      | Missing files | {{missing_file_count}} |

      **Full Migration History:**
      | Seq | Name | Local | DB | Rollback |
      |-----|------|-------|----|----------|
      {{#each all_migrations}}
      | {{seq}} | {{description}} | {{#if in_local}}✓{{else}}—{{/if}} | {{#if in_db}}✓ ({{applied_at}}){{else}}—{{/if}} | {{#if rollback_exists}}✓{{else}}❌{{/if}} |
      {{/each}}

      {{#if pending_count > 0}}
      ⚠️ **Action Required**: {{pending_count}} migration(s) need to be applied to database.
      {{/if}}

      {{#if orphaned_count > 0}}
      ⚠️ **Warning**: {{orphaned_count}} migration(s) in database are not tracked in local manifest.
      This may indicate another developer applied migrations not yet pulled into this codebase.
      {{/if}}

      {{#if missing_file_count > 0}}
      ❌ **Error**: {{missing_file_count}} migration(s) in manifest have no corresponding .sql file on disk.
      {{/if}}
